<template>
  <div class="text-to-video-panel">
    <!-- 1. 标题区域 -->
    <div class="panel-header">
      <div class="panel-title">{{ t('generateVideo') }}</div>
      <p class="panel-description">{{ t('createYourVideo') }}</p>
    </div>

    <!-- 2. 提示词输入 -->
    <div class="form-section">
      <label class="form-label">{{ t('prompt') }}</label>
      <p class="form-help">{{ t('promptDescription') }}</p>
      <el-input
        v-model="formData.prompt"
        type="textarea"
        :placeholder="t('promptPlaceholderVideo')"
        :rows="4"
        class="prompt-input"
      />
    </div>

    <!-- 3. 模型选择 -->
    <div class="form-section">
      <label class="form-label">{{ t('model') }}</label>
      <p class="form-help">{{ t('modelDescriptionVideo') }}</p>
      <OptionSelector 
        v-model="formData.model"
        type="video"
        :placeholder="t('selectModel')"
        :show-radio="true"
        :show-description="true"
      />
    </div>

    <!-- 4. 清晰度选择 -->
    <div class="form-section">
      <label class="form-label">{{ t('resolution') }}</label>
      <div class="resolution-group">
        <div 
          v-for="item in resolutionOptionsRef" 
          :key="item.value" 
          class="resolution-option"
          :class="{ 'active': formData.resolution === item.value }"
          @click="handleResolutionChange(item.value)"
        >
          {{ item.label }}
        </div>
      </div>
    </div>

    <!-- 5. 时长选择 -->
    <div class="form-section">
      <label class="form-label">{{ t('duration') }}</label>
      <div class="duration-group">
        <div 
          v-for="item in durationOptionsRef" 
          :key="item.value" 
          class="duration-option"
          :class="{ 'active': formData.duration === item.value }"
          @click="handleDurationChange(item.value)"
        >
          {{ item.label }}
        </div>
      </div>
    </div>

    <!-- 6. 视频比例选择 -->
    <div class="form-section">
      <label class="form-label">{{ t('videoDimensions') }}</label>
      <p class="form-help">{{ t('selectVideoDimensions') }}</p>
      <RatioSelector 
        v-model="formData.ratio"
        :type="'video'"
      />
    </div>

    <!-- 7. Seed选项 -->
    <div class="form-section seed-section-box">
      <OptionalSeedInput
        v-model="formData.seed"
        :title="t('seed')"
        :description="t('videoGenerationSeed')"
        :placeholder="t('seedPlaceholder')"
        @expand-change="showAdvancedOptions = $event"
      />
    </div>

    <!-- 8. 生成按钮 -->
    <div class="form-actions">
      <el-button
        :loading="isGenerating"
        @click="onGenerateClick"
        :disabled="isButtonDisabled"  
        class="generate-button"
        :class="{'disabled': isButtonDisabled}"
        block
      >
        <l-img w="18px" h="18px" src="/static/images/video-icon.png"></l-img>
        {{ t('generateVideo') }}
      </el-button>
    </div>
  </div>
</template>

<script setup>
import { ref, reactive, computed, onMounted, onBeforeUnmount } from 'vue';
import { useI18n } from 'vue-i18n';
import { ElMessage } from 'element-plus';
import OptionSelector from '@/components/business/components/option-selector.vue';
import RatioSelector from '@/components/business/components/ratio-selector.vue';
import OptionalSeedInput from '@/components/business/components/optional-seed-input.vue';
import LImg from '@/components/l-img.vue';
import { resolutionOptions, durationOptions, getResolutionString } from '@/types/panel-options';
import { addTaskToPolling, TaskType } from '@/presenter/media-task-polling';
import { mediaTaskEventBus, clearMediaTaskEventListeners } from '@/presenter/media-task-events';
import router from '@/router';
import { useMediaGenerationStore } from '@/store/modules/media-generation';
import { apiGeneration } from '@/api/api-generation';

const { t } = useI18n();
const mediaStore = useMediaGenerationStore();

// 轮询管理器通过函数调用

// 定义状态
const isGenerating = ref(false);
const showAdvancedOptions = ref(false);
// 当前任务ID，用于事件过滤
const currentTaskId = ref(null);

// 表单数据 - 不设置默认选中值
const formData = reactive({
  prompt: '',
  model: '',
  resolution: '',
  duration: '',
  ratio: '',
  seed: ''
});


// 分辨率选项
const resolutionOptionsRef = ref(resolutionOptions);

// 时长选项
const durationOptionsRef = ref(durationOptions);


// 定义事件
const emit = defineEmits(['generate-success', 'generate-error', 'generate-create', 'loading']);

// 计算属性：按钮禁用状态
const isButtonDisabled = computed(() => {
   return !formData.prompt || 
          !formData.model || 
          !formData.resolution || 
          !formData.duration || 
         !formData.ratio ||
         isGenerating.value;
 });

// 处理任务完成事件
const handleTaskCompleted = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    emit('generate-success', res);
    isGenerating.value = false;
    currentTaskId.value = null;
  }
};

// 处理任务失败事件
const handleTaskFailed = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    emit('generate-error', res);
    isGenerating.value = false;
    currentTaskId.value = null;
  }
};

// 处理任务状态更新事件
const handleTaskStatusUpdate = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    // 更新进度等信息
    console.log(`Text-to-video progress: ${res.res.progress}%`);
    emit('loading', true, res.res.estimated_time || null);
  }
};

// 业务逻辑区域


// 处理生成按钮点击
const onGenerateClick = async () => {
  try {
    emit('generate-create');
    emit('loading', true, null);
    isGenerating.value = true;
    
    // 准备请求数据，映射到API期望的格式
    // 注意：保持表单验证逻辑不变，但API只发送必要字段
    const requestData = {
      prompt: formData.prompt.trim(),
      model: formData.model,
      duration: parseInt(formData.duration),
      aspect_ratio: formData.ratio,
      negative_prompt: '' // 固定传空字符串
    };

    console.log('Text-to-video generating with data:', requestData);
    
    // 调用真实的API
    const apiResult = await apiGeneration.textToVideo(requestData);
    
    // 设置路由meta并添加到轮询管理器
const meta = router.currentRoute.value.meta || {};
router.currentRoute.value.meta = { ...meta, taskId: apiResult.task_id, type: TaskType.VIDEO };
    addTaskToPolling(apiResult.task_id, TaskType.VIDEO);
    
    // 设置当前任务ID
    currentTaskId.value = apiResult.task_id;
    
  } catch (error) {
    emit('loading', false, null);
    isGenerating.value = false;
    emit('generate-error', error);
  }
};

// 处理清晰度选择
const handleResolutionChange = (value) => {
  formData.resolution = value;
};

// 处理时长选择
const handleDurationChange = (value) => {
  formData.duration = value;
};

// 生命周期钩子
onMounted(() => {
  // 绑定媒体任务事件监听器（只绑定一次）
  mediaTaskEventBus.on('task-completed', handleTaskCompleted);
  mediaTaskEventBus.on('task-failed', handleTaskFailed);
  mediaTaskEventBus.on('task-status-update', handleTaskStatusUpdate);
});

// 组件卸载前清理
onBeforeUnmount(() => {
  // 清理事件监听器（只清理一次）
  clearMediaTaskEventListeners();
  
  // 清除路由meta中的taskId
  if (router?.currentRoute?.value?.meta) {
    router.currentRoute.value.meta.taskId = null;
  }
});
</script>

